@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public ResponseEntity<EntityModel<Order>> getOrder(@PathVariable Long id) {
        Order order = orderService.findById(id);

        // Level 3: HATEOAS - Adding hypermedia links to the response representation
        EntityModel<Order> orderModel = EntityModel.of(order,
            linkTo(methodOn(OrderController.class).getOrder(id)).withSelfRel(),
            linkTo(methodOn(OrderController.class).cancelOrder(id)).withRel("cancel-order"),
            linkTo(methodOn(CustomerController.class).getCustomer(order.getCustomerId())).withRel("customer"));

        return ResponseEntity.ok(orderModel);
    }
}
